Here is a complete, standalone implementation of an LRU (Least Recently Used) cache in Rust.

It uses `std::collections::HashMap` for O(1) lookups and a custom **Doubly Linked List** (using `Rc` and `RefCell`) to manage the order of usage in O(1).

### The Implementation

```rust
use std::cell::RefCell;
use std::collections::HashMap;
use std::rc::Rc;

// Type alias for a shared, mutable node
type NodeRef<K, V> = Rc<RefCell<Node<K, V>>>;

// The Node structure
struct Node<K, V> {
    key: K,
    value: V,
    prev: Option<NodeRef<K, V>>,
    next: Option<NodeRef<K, V>>,
}

impl<K, V> Node<K, V> {
    fn new(key: K, value: V) -> Self {
        Node {
            key,
            value,
            prev: None,
            next: None,
        }
    }
}

// The LRU Cache structure
pub struct LruCache<K, V> {
    map: HashMap<K, NodeRef<K, V>>,
    head: Option<NodeRef<K, V>>, // Most Recently Used
    tail: Option<NodeRef<K, V>>, // Least Recently Used
    capacity: usize,
}

impl<K, V> LruCache<K, V>
where
    K: Eq + std::hash::Hash + Clone,
{
    pub fn new(capacity: usize) -> Self {
        LruCache {
            map: HashMap::with_capacity(capacity),
            head: None,
            tail: None,
            capacity,
        }
    }

